def require(ok, label):
    if not ok:
        raise ValueError(label)

def digest(data):
    return hashlib.sha256(data).hexdigest()

def main():
    raw = (REPO / MANIFEST_PATH).read_bytes()
    require(digest(raw) == MANIFEST_SHA, 'input manifest identity')
    manifest = json.loads(raw)
    require(manifest['schema'] == 'shared-mediator-publication-inputs-v1', 'schema')
    members = manifest['members']
    require(len(AUDIT_INPUT_PATHS) == len(set(AUDIT_INPUT_PATHS)), 'duplicate input')
    require(set(AUDIT_INPUT_PATHS) == set(members) | {MANIFEST_PATH}, 'input closure')
    data = {}
    for name, item in members.items():
        path = PurePosixPath(name)
        require(not path.is_absolute() and '..' not in path.parts, 'relative path')
        value = (REPO / name).read_bytes()
        require(len(value) == item['bytes'] and digest(value) == item['sha256'],
                'input bytes: ' + name)
        data[name] = value
    note = data[NOTE]
    front = note.split(b'---', 2)[1]
    require(b'canonical_parent_binding_complete: true' in front,
            'root canonical binding is required; this source proposal is not executable evidence')
    mapping = json.loads(data[PACKET + '/BODY_MAP.json'])
    for key in ('two_copy', 'single_port'):
        item = mapping['bodies'][key]
        body = note[item['start']:item['end']]
        require(len(body) == item['bytes'] and digest(body) == item['sha256'],
                'complete raw body: ' + key)
        require(note.count(body) == 1, 'unique raw body: ' + key)
    deps = json.loads(data[PACKET + '/DEPENDENCIES.json'])
    require(deps['single_port_depends_on_two_copy'] is False, 'alternative independence')
    require(deps['autonomous_source_role'] == 'provenance_only', 'no autonomous theorem import')
    require(len(deps['direct_canonical_dependencies']) == 2, 'exact two geometry premises')
    for item in mapping['canonical_geometry_bodies']:
        body = data[item['canonical_path']][item['start']:item['end']]
        require(len(body) == item['bytes'] and digest(body) == item['sha256'],
                'canonical geometry raw body')
        require(data[item['canonical_path']].count(body) == 1, 'unique canonical geometry body')
    state = json.loads(data[PACKET + '/PUBLICATION_STATE.json'])
    require(state['kind'] == 'dated_source_proposal_not_actual_binding', 'proposal history')
    for field in ('canonical_binding', 'primary_execution', 'cache_execution',
                  'graph_execution', 'publication_action', 'retained_audit'):
        require(state[field] is None, 'no invented historical outcome: ' + field)
    expected_parents = set(['docs/FINITE_RESERVOIR_BOUNDARY_CLOCK_PREPARATION_BOUNDED_THEOREM_NOTE_2026-10-15.md', 'docs/FINITE_LOCAL_CLOCK_MEMORY_RESOURCES_BOUNDED_THEOREM_NOTE_2026-10-15.md'])
    require({item['path'] for item in deps['direct_canonical_dependencies']} == expected_parents,
            'canonical dependency endpoints')
    require({item['canonical_path'] for item in mapping['canonical_geometry_bodies']} == expected_parents,
            'canonical body endpoints')
    binding = json.loads(data[PACKET + '/ACTUAL_BINDING.json'])
    require(binding['kind'] == 'actual_canonical_source_binding', 'actual binding kind')
    bound = binding['canonical_note']
    require(bound['path'] == NOTE and bound['bytes'] == len(note) and bound['sha256'] == digest(note),
            'actual note binding')
    require(binding['raw_bodies'] == mapping['bodies'], 'actual body binding')
    require(binding['canonical_geometry_parents'] == deps['direct_canonical_dependencies'], 'actual parent binding')

    print(json.dumps({'result': 'source_integrity_verified',
                      'scope': 'Exact source and package integrity only; no mathematical or physical verification.',
                      'scientific_programs_run': 0, 'historical_runs_replayed': 0,
                      'publication_or_retained_status_certified': False}, sort_keys=True))
    print('per_element: exact sampled-program proof sources checked as bytes; scientific formulas are not executed')
    print('per_site: literal geometry source identities checked; no lattice adjacency analysis is rerun')
    print('per_mode: the admitted N_X=1 and full auxiliary output contracts are source claims, not simulated here')
    print('per_block: both independent proof bodies and their actual source-review receipts are integrity inputs')
    print('lattice_wide: this runner establishes source closure only and supplies no native realization or audit status')

if __name__ == '__main__':
    main()
